import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { execFileSync } from 'node:child_process'

async function loadTypeScript() {
  try {
    return (await import('typescript')).default
  } catch {
    const globalRoot = execFileSync('npm', ['root', '-g'], { encoding: 'utf8' }).trim()
    return (await import(pathToFileURL(path.join(globalRoot, 'typescript/lib/typescript.js')).href)).default
  }
}
const ts = await loadTypeScript()

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const entry = path.join(root, 'src/client/index.ts')
const out = path.join(root, 'lib/client.js')
const packageJson = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'))
const packageId = packageJson.name
const allowedExternals = new Set(['react'])
const transpiled = new Map()

function posix(file) { return path.relative(root, file).split(path.sep).join('/') }
function candidates(from, spec) {
  const raw = path.resolve(path.dirname(from), spec)
  const base = raw.replace(/\.js$/u, '')
  return [`${base}.ts`, `${base}.tsx`, `${base}.mts`, `${base}.cts`, path.join(base, 'index.ts')]
}
function resolveLocal(from, spec) {
  for (const file of candidates(from, spec)) if (fs.existsSync(file)) return file
  throw new Error(`client bundle: cannot resolve ${spec} from ${posix(from)}`)
}
function compile(file) {
  file = path.resolve(file)
  const id = posix(file)
  if (transpiled.has(id)) return
  const source = fs.readFileSync(file, 'utf8')
  const result = ts.transpileModule(source, {
    fileName: file,
    compilerOptions: {
      target: ts.ScriptTarget.ES2022,
      module: ts.ModuleKind.CommonJS,
      moduleResolution: ts.ModuleResolutionKind.Node10,
      jsx: ts.JsxEmit.React,
      esModuleInterop: false,
      sourceMap: false,
      inlineSourceMap: false,
      importsNotUsedAsValues: ts.ImportsNotUsedAsValues.Remove,
    },
    reportDiagnostics: true,
  })
  const errors = (result.diagnostics ?? []).filter(d => d.category === ts.DiagnosticCategory.Error)
  if (errors.length) throw new Error(`client bundle transpile failed for ${id}: ${errors.map(d => ts.flattenDiagnosticMessageText(d.messageText, '\n')).join('; ')}`)
  transpiled.set(id, result.outputText)
  // Follow only runtime CommonJS requires. Type-only imports have already
  // disappeared, which is the crucial browser/Node boundary.
  for (const match of result.outputText.matchAll(/require\(["']([^"']+)["']\)/gu)) {
    const spec = match[1]
    if (spec.startsWith('.')) compile(resolveLocal(file, spec))
  }
}
compile(entry)

// Audit emitted runtime requires. Type-only DSH imports must have disappeared.
for (const [id, code] of transpiled) {
  for (const match of code.matchAll(/require\(["']([^"']+)["']\)/gu)) {
    const spec = match[1]
    if (spec.startsWith('.')) continue
    if (!allowedExternals.has(spec)) throw new Error(`client bundle: unexpected runtime external ${JSON.stringify(spec)} in ${id}`)
  }
}

const moduleTable = [...transpiled].map(([id, code]) => {
  return `${JSON.stringify(id)}: function(module, exports, require) {\n${code}\n}`
}).join(',\n')

const bundle = `/* dsh-workbench browser bundle: generated by scripts/build-client-bundle.mjs */\n(function () {\n  'use strict';\n  var target = globalThis.__ModuleLoader__;\n  if (!target || typeof target.load !== 'function') throw new Error('dsh-workbench: __ModuleLoader__.load is unavailable');\n  target.load({\n    id: ${JSON.stringify(packageId)},\n    factory: function (externalRequire) {\n      var modules = {\n${moduleTable}\n      };\n      var cache = Object.create(null);\n      function normalize(parts) {\n        var out = [];\n        for (var i = 0; i < parts.length; i++) {\n          var part = parts[i];\n          if (!part || part === '.') continue;\n          if (part === '..') out.pop(); else out.push(part);\n        }\n        return out.join('/');\n      }\n      function resolveLocal(from, spec) {\n        var base = from.slice(0, from.lastIndexOf('/') + 1);\n        var resolved = normalize((base + spec).split('/'));\n        if (resolved.endsWith('.js')) resolved = resolved.slice(0, -3);\n        var choices = [resolved + '.ts', resolved + '.tsx', resolved + '.mts', resolved + '.cts', resolved + '/index.ts'];\n        for (var i = 0; i < choices.length; i++) if (Object.prototype.hasOwnProperty.call(modules, choices[i])) return choices[i];\n        throw new Error('dsh-workbench: missing bundled module ' + spec + ' from ' + from);\n      }\n      function load(id) {\n        if (Object.prototype.hasOwnProperty.call(cache, id)) return cache[id].exports;\n        var body = modules[id];\n        if (typeof body !== 'function') throw new Error('dsh-workbench: unknown bundled module ' + id);\n        var module = { exports: {} };\n        cache[id] = module;\n        body(module, module.exports, function (spec) {\n          return spec && spec[0] === '.' ? load(resolveLocal(id, spec)) : externalRequire(spec);\n        });\n        return module.exports;\n      }\n      return load('src/client/index.ts');\n    }\n  });\n})();\n`

fs.mkdirSync(path.dirname(out), { recursive: true })
fs.writeFileSync(out, bundle)

// The dynamic loader consumes only lib/client.js. Keep declarations but remove
// modular browser JS so the published artifact has one browser execution face.
for (const dir of [path.join(root, 'lib/client')]) {
  if (!fs.existsSync(dir)) continue
  for (const name of fs.readdirSync(dir)) if (name.endsWith('.js')) fs.rmSync(path.join(dir, name))
}
console.log(`built ${path.relative(root, out)} (${Buffer.byteLength(bundle)} bytes, ${transpiled.size} modules)`)
